{"function":"() => {
const parse=c=>{const m=c.match(/[\d.]+/g).map(Number);return m};
const lum=([r,g,b])=>{const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)};return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b)};
const bg=el=>{while(el){const c=getComputedStyle(el).backgroundColor;const p=parse(c);if(p.length<4||p[3]>0)return p;el=el.parentElement}return [255,255,255]};
const out=[];
const seen=new Set();
document.querySelectorAll('#root *').forEach(el=>{
 const t=[...el.childNodes].filter(n=>n.nodeType==3&&n.textContent.trim()).map(n=>n.textContent.trim()).join(' ');
 const isInput=el.matches('input,textarea');
 if(!t && !isInput) return;
 const cs=getComputedStyle(el);
 if(cs.display=='none'||cs.visibility=='hidden') return;
 const r=el.getBoundingClientRect(); if(r.width==0) return;
 const fg=parse(cs.color);const b=bg(el);
 const L1=lum(fg),L2=lum(b);const cr=(Math.max(L1,L2)+0.05)/(Math.min(L1,L2)+0.05);
 let ph=null;
 if(isInput&&el.placeholder){const pc=getComputedStyle(el,'::placeholder');const pf=parse(pc.color);ph={c:pc.color,cr:((Math.max(lum(pf),L2)+0.05)/(Math.min(lum(pf),L2)+0.05)).toFixed(2)}}
 out.push([el.tagName+(el.id?'#'+el.id:'')+'.'+el.className, (t||'').slice(0,30), cs.fontSize, cs.fontWeight, cs.color, 'bg'+b.join(','), cr.toFixed(2), ph?JSON.stringify(ph):''].join(' | '));
});
return out.join('\n');
}"}

